        "f7_full": "北口ロータリーのすぐ近くで1980年から愛される洋菓子店。看板商品の名は「庄和やきたてふる里ぽてと」という。昭和29年（1954年）、南桜井村・川辺村・富多村・宝珠花村の4村が合併して生まれた「庄和町（庄和村）」の名が、平成の大合併で春日部市となった今も、お菓子の名前として誇り高く焼き上げられている。\n\nさつま芋の優しい甘みが広がる「庄和やきたてふる里ぽてと」と、温かみのあるショーケース。\n\n洋菓子で一息ついたら、西へ歩いて8分。米島など5か村を見守ってきた樹齢800年の巨木を訪ねよう。",
        "is_final": false,
